def transform(grid):
    h, w = len(grid), len(grid[0])

    def spans(length, cuts):
        result = []
        start = 0
        for i in range(length):
            if i in cuts:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < length:
            result.append((start, length))
        return result

    row_cuts = {r for r in range(h) if all(v == 6 for v in grid[r])}
    col_cuts = {c for c in range(w) if all(grid[r][c] == 6 for r in range(h))}
    row_spans = spans(h, row_cuts)
    col_spans = spans(w, col_cuts)

    tiles = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            tile = [row[c0:c1] for row in grid[r0:r1]]
            points = [(r, c) for r in range(len(tile)) for c in range(len(tile[0]))
                      if tile[r][c] not in (6, 7)]
            if points:
                rs = [p[0] for p in points]
                cs = [p[1] for p in points]
                cy = (min(rs) + max(rs)) / 2
                cx = (min(cs) + max(cs)) / 2
            else:
                cy = cx = 0
            tiles.append((tile, cx, cy))

    xs = [t[1] for t in tiles]
    ys = [t[2] for t in tiles]
    horizontal = max(xs) - min(xs) >= max(ys) - min(ys)

    if horizontal:
        tiles.sort(key=lambda t: (-t[1], -t[2]))
        out = [[] for _ in range(len(tiles[0][0]))]
        for i, (tile, _, _) in enumerate(tiles):
            if i:
                for row in out:
                    row.append(6)
            for r, row in enumerate(tile):
                out[r].extend(row)
        return out
    else:
        tiles.sort(key=lambda t: (-t[2], -t[1]))
        out = []
        for i, (tile, _, _) in enumerate(tiles):
            if i:
                out.append([6] * len(tile[0]))
            out.extend([row[:] for row in tile])
        return out
